// Alert once per campaign per 30 minutes while it is not RUNNING. A healthy
// read (200 + all_running) clears the suppression so the next outage alerts
// immediately. Static data persists across executions of an ACTIVE workflow.
const SUPPRESS_MS = 30 * 60 * 1000;
const ROUTE_KEY = '__campaign_state_route__';

const item = $input.first()?.json || {};
const status = Number(item.statusCode ?? item.status ?? 0) || 0;
const body = (item.body && typeof item.body === 'object') ? item.body : {};
const campaigns = Array.isArray(body.campaigns) ? body.campaigns : [];

const st = $getWorkflowStaticData('global');
if (!st.lastAlert || typeof st.lastAlert !== 'object') st.lastAlert = {};
const now = Date.now();

if (status === 200 && body.all_running === true) {
  st.lastAlert = {};
  return [];
}

const due = (key) => !st.lastAlert[key] || (now - Number(st.lastAlert[key])) >= SUPPRESS_MS;
const alerts = [];

if (campaigns.length) {
  for (const c of campaigns) {
    if (c.ok === true) { delete st.lastAlert[c.campaign]; continue; }
    if (!due(c.campaign)) continue;
    st.lastAlert[c.campaign] = now;
    const state = c.state ? String(c.state) : 'UNREADABLE';
    alerts.push({ campaign: c.campaign, state, text: `\u26A0 CAPACITY RANKER: ${c.campaign} is ${state} during dial hours \u2014 floor is not dialing it. Check Five9 now.` });
  }
} else {
  // The check itself failed (LP-MCP down, timeout, non-JSON). We cannot
  // confirm the campaigns are RUNNING, which is exactly when a human must look.
  if (due(ROUTE_KEY)) {
    st.lastAlert[ROUTE_KEY] = now;
    const detail = item.error?.message || item.error || (status ? `HTTP ${status}` : 'no response');
    alerts.push({ campaign: null, state: null, text: `\u26A0 CAPACITY RANKER: campaign-state check FAILED (${detail}) \u2014 cannot confirm the Data campaigns are RUNNING. Check Five9 now.` });
  }
}

return alerts.map((a) => ({ json: a }));
